import {compare,cleanComparison,COMP_DEFAULTS} from './comparison-engine.js?v=17';
import {zip,saveFile} from './files.js?v=11';
import {jpegPdf} from './pdf.js?v=11';
const money=n=>new Intl.NumberFormat('cs-CZ',{maximumFractionDigits:0}).format(n)+' Kč',key='muj-dip-comparison-v1';
const disclaimer='Pouze obecná vzdělávací simulace pro českého daňového rezidenta, nepodnikatelský majetek a nové smlouvy. Nejde o doporučení konkrétního produktu ani posouzení jeho vhodnosti. Upozornění nevylučuje odpovědnost, kterou nelze ze zákona omezit. Orientační scénář bez záruky, nikoli investiční ani daňové doporučení. Výnos není garantovaný. Pravidla roku 2026 jsou pro ilustraci zachována po celý horizont. Daňové úspory nejsou reinvestovány. Investice mohou ztrácet hodnotu.';
const methodology='Časový test je aproximován po měsících: osvobozeny jsou nákupy starší než 36 měsíců, nikoli nákup přesně před 36 měsíci. Skutečnou lhůtu je nutné posoudit podle konkrétních dnů nabytí a prodeje. Roční výstupní daň z DIP je orientační přírůstek daně se základní slevou a sazbami 15 / 23 %, bez finálního zaokrouhlení daňového přiznání. Daň v meziletech není odečítána z portfolia, jde jen o hypotetický výpočet při řádném prodeji. Případnou daň z obchodů uvnitř DIP před řádným výběrem je nutné uhradit mimo DIP. Vklady na konci měsíce; státní příspěvek modelově měsíčně (ve skutečnosti připisován čtvrtletně). Roční výnos převeden na efektivní měsíční sazbu; roční náklady odečítány po dvanáctinách před vkladem. Vstupní poplatek z vlastních a firemních plateb, nikoli ze státní podpory. Výkonnostní poplatek DPS je zjednodušen jako procento kladného ročního zisku po správě; skutečná úplata dle statutu používá průměrné hodnoty jednotky a historické maximum, proto se může lišit. Pro přesnější scénář vložte čistý výnos po všech průběžných nákladech. Publikované čisté výnosy se nesmí znovu snižovat o tytéž poplatky.';
const sources=[['Zákon o daních z příjmů č. 586/1992 Sb.','https://e-sbirka.gov.cz/sb/1992/586'],['Zákon o DPS č. 427/2011 Sb.','https://e-sbirka.gov.cz/sb/2011/427'],['MF: výše státních příspěvků','https://mf.gov.cz/cs/ministerstvo/media/tiskove-zpravy/2024/zmeny-statniho-prispevku-ve-iii-penzijnim-piliri-56059'],['Finanční správa: změny roku 2026','https://financnisprava.gov.cz/cs/financni-sprava/media-a-verejnost/tiskove-zpravy-gfr/tiskove-zpravy-2026/danove-novinky-pro-rok-2026'],['MF: podpora a zdanění DIP','https://mf.gov.cz/cs/financni-trh/ochrana-spotrebitele/aktuality/2024/dlouhodoby-investicni-produkt-a-danova-podpora-pro-54732'],['Finanční správa: pravidla 2026','https://financnisprava.gov.cz/cs/dane/dane/dan-z-prijmu/zamestnanci-zamestnavatele/dotazy-a-odpovedi/2026/aktualni-dotazy-a-odpovedi-k-dani-z'],['ČSOB: daň při výplatě penze','https://www.csob-penze.cz/caste-dotazy/faq-penzijko-a-dane/']];
const titles={otherSales:'Jiné hrubé prodeje cenných papírů v roce výběru',dipProfile:'Předvolba DIP',dpsProfile:'Předvolba DPS',loyalty:'Volitelný model bonusu',loyaltyRate:'Odhad zhodnocení věrnostního konta',age:'Věk při založení',years:'Doba spoření',own:'Vlastní vklad měsíčně',employer:'Firma měsíčně',salary:'Hrubá mzda měsíčně',otherOwn:'Jiné využité odpočty ročně',otherEmployer:'Jiné příspěvky firmy ročně',inflation:'Inflace ročně',pensioner:'Přiznaný starobní důchod po celý horizont',dipRate:'Výnos DIP ročně',dpsRate:'Výnos DPS ročně',dipEntry:'Vstupní poplatek DIP',dpsEntry:'Vstupní poplatek DPS',dipFee:'Celkové průběžné náklady DIP ročně',dpsFee:'Správa DPS ročně',dpsPerformance:'Výkonnostní poplatek DPS',netReturns:'Výnosy po průběžných nákladech',dipTax:'Zdanění DIP',payout:'Výplata DPS'};
let state={...COMP_DEFAULTS},result;try{const saved=localStorage.getItem(key);if(saved)state=cleanComparison(JSON.parse(saved));}catch{}
const field=(k,unit='Kč',min=0,max=100000,step='any')=>`<label class="field">${titles[k]}<div class="input-wrap"><input data-cmp="${k}" type="number" min="${min}" max="${max}" step="${step}" value="${state[k]}"><span>${unit}</span></div></label>`;
const select=(k,items)=>`<label class="field">${titles[k]}<select data-cmp="${k}">${items.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label>`;
const section=document.createElement('section');section.id='comparison';section.className='panel';section.hidden=true;
section.innerHTML=`<div class="comparison-heading"><div><span class="eyebrow">SAMOSTATNÝ KALKULÁTOR · PRAVIDLA 2026</span><h2>DPS × DIP. Srovnání modelových scénářů.</h2><p>Stejný rozpočet, dvě samostatné alternativy. Nastavení tohoto srovnání nemění váš původní plán.</p></div><button class="button outline" id="cmp-reset">Obnovit příklad</button></div><div class="layout"><aside class="card inputs"><h3>Společné zadání</h3><div class="two">${field('age','let',18,90,1)}${field('years','let',1,50,1)}</div>${field('own')}${field('employer')}${field('inflation','%',0,30)}<details><summary>Daně a další podmínky</summary>${field('salary','Kč',0,1000000)}${field('otherOwn','Kč',0,48000)}${field('otherEmployer','Kč',0,1000000)}${field('otherSales','Kč',0,1000000000)}${select('pensioner',[[0,'Ne'],[1,'Ano – bez státního příspěvku']])}</details><hr><h3>DIP – modelový fond</h3>${select('dipProfile',[['model','Modelový fond'],['etf','ETF · vlastní odhad nákladů'],['custom','Vlastní nastavení']])}<p class="small muted">DIP – modelový fond. Předvyplněné sazby jsou volně upravitelné předpoklady, nikoli sazebník nebo prognóza konkrétního poskytovatele. ETF je pouze alternativní model nákladů.</p>${field('dipRate','%',-100,100)}${field('dipEntry','%',0,100)}${field('dipFee','%',0,20)}${select('dipTax',[['test','Prodej všeho: test každého nákupu 3 roky'],['exempt','Předpoklad: veškeré prodeje osvobozené'],['taxable','Předpoklad: veškerý kladný zisk zdanitelný']])}<hr><h3>Modelový DPS</h3><p class="small muted">Modelový DPS: nová smlouva od roku 2024, založení nyní. Vstup, správu a výkonnostní úplatu nastavte podle svého scénáře. Nejde o konkrétní penzijní společnost.</p>${select('dpsProfile',[['dynamic','Modelový dynamický DPS · 1 % + 15 %'],['balanced','Modelový vyvážený DPS · 1 % + 15 %'],['conservative','Modelový konzervativní DPS · 0,4 % + 10 %'],['custom','Vlastní DPS']])}<p class="small muted">Předvolby upravují modelové poplatky. Zadaný výnos je samostatný předpoklad, nikoli odhad výkonnosti strategie.</p>${field('dpsRate','%',-100,100)}${field('dpsEntry','%',0,100)}${field('dpsFee','%',0,20)}${field('dpsPerformance','%',0,50)}${select('payout',[['lump','Jednorázově: 15 % z kladného výnosu'],['pension','Penze alespoň 10 let: osvobozená']])}<details><summary>Volitelný model bonusu</summary>${select('loyalty',[[0,'Bez bonusu'],[1,'Model 25 % ze správy na oddělené konto']])}${field('loyaltyRate','%',0,20)}<p class="small muted">Samostatný ilustrační bonus ve výši 25 % modelové správy do 65 let. Není standardní vlastností DPS ani nárokem klienta. Odhad je před případnou daní a mimo celkový výsledek. Podmínky skutečného bonusu je nutné ověřit u poskytovatele.</p></details><hr>${select('netReturns',[[0,'Zadaný výnos před průběžnými náklady'],[1,'Zadaný výnos již po průběžných nákladech']])}<p class="small muted">V čistém režimu se správa a výkonnostní úplata znovu neodečítají; vstupní poplatek zůstává. Náklady uvnitř čistého výnosu nelze z této sazby vyčíslit.</p></aside><div class="results"><div id="cmp-warning" class="callout"></div><section class="hero card"><div class="hero-top"><span>MODELOVÝ VÝSLEDEK PO DANI + ÚSPORA DANĚ MIMO PRODUKT</span></div><div class="cmp-totals"><div><span>● DIP</span><strong id="cmp-dip"></strong></div><div><span>● DPS</span><strong id="cmp-dps"></strong></div></div><p id="cmp-verdict"></p><p id="cmp-why" class="small"></p></section><section class="card chart-card"><div class="chart-heading"><h2>Vývoj po dani včetně daňových úspor</h2></div><div class="legend"><span><i style="background:#2563eb"></i>DIP</span><span><i style="background:#111111"></i>DPS</span><span><i style="background:#dc2626"></i>Po inflaci (přerušovaně)</span></div><div id="cmp-chart" class="chart" role="img" aria-label="Srovnání vývoje DIP a DPS"></div><p class="small muted">Křivky zobrazují hodnotu po modelové dani při výběru v daném roce plus kumulované daňové úspory mimo produkt, bez jejich reinvestování. Koncové hodnoty odpovídají horním výsledkům. Daň se neodečítá průběžně každý rok. Před splněním podmínek nejde o dostupnou částku bez dopadů předčasného ukončení. Hodnoty po inflaci: červeně, DIP krátké a DPS dlouhé čárkování.</p></section><section class="card table-card"><h2>Co tvoří výsledek</h2><div class="table-scroll"><table><thead><tr><th>Položka</th><th>🔵 DIP</th><th>⚫ DPS</th></tr></thead><tbody id="cmp-summary"></tbody></table></div><p id="cmp-payout-note" class="small muted"></p></section><section class="card table-card"><h2>Výpočet po jednotlivých letech</h2><div class="table-scroll"><table><thead><tr><th>Rok / věk</th><th>DIP před daní</th><th>DPS před daní</th><th>DIP po modelové dani¹</th><th>DPS po modelové dani¹</th><th>Úspora daně DIP</th><th>Úspora daně DPS</th></tr></thead><tbody id="cmp-years"></tbody></table></div><p class="small muted">¹ Výpočet daně jako při řádné výplatě v daném roce. Před splněním věku a doby nejde o dostupnou částku; případné vracení podpory při předčasném ukončení zde není modelováno.</p></section><section class="card explanation"><h2>Uložit a exportovat toto srovnání</h2><div class="cmp-actions"><button id="cmp-save">Uložit srovnání</button><button data-cmp-export="xlsx">Excel ↓</button><button data-cmp-export="pdf">PDF ↓</button><button data-cmp-export="png">PNG ↓</button><button data-cmp-export="json">JSON ↓</button><button data-cmp-export="csv">Tabulka CSV ↓</button><label class="import">Načíst JSON<input id="cmp-import" type="file" accept=".json"></label></div><p class="small muted">Horní Uložit / Export / PDF / Obnovit pracují na této záložce se srovnáním. Import srovnání podporuje JSON; Excel, PDF a PNG jsou výstupní přehledy.</p><p id="cmp-status" role="status" aria-live="polite"></p></section><section class="card explanation"><h2>Jak srovnání číst</h2><ul><li>🔵 DIP: daňový odpočet od první koruny; není automaticky osvobozený od daně z obchodů. Automatický režim posuzuje hodnotový test 100 000 Kč z hrubých prodejů včetně jiných zadaných prodejů a pak časový test jednotlivých nákupů. Neosvobozený zisk přičítá k modelovému základu daně a zohledňuje sazby 15 / 23 %. Uvedená mzda je předpokládána i v roce výběru; další příjmy a úlevy kromě uvedených nejsou zahrnuty.</li><li>⚫ DPS: státní podpora 20 % vlastního vkladu od 500 Kč, nejvýše 340 Kč měsíčně; odpočet nad 1 700 Kč (u důchodce od první koruny, bez státního příspěvku).</li><li>🟢 Odpočet nejvýše 48 000 Kč ročně dohromady. Každá alternativa využívá tentýž zbývající limit samostatně. Úspora počítána z uvedené mzdy, základní slevy a sazeb 15 / 23 % pro rok 2026.</li><li>🔴 Příspěvky firmy: osvobození 50 000 Kč ročně na osobu společně. Nadlimitní část se může vložit, ale zdaní se ve mzdě; srovnání její dodatečné odvody nezapočítává do výsledku.</li><li>Obě varianty: nová smlouva, minimálně 10 let a věk 60. Předčasné ukončení není propočteno. U staršího DPS se mohou lišit podmínky i zdanění příspěvků zaměstnavatele.</li><li>Penze DPS na 10 a více let není jednorázová hotovost v 60 letech. Srovnání uvádí kapitál určený k výplatě, bez výnosů během vyplácení a bez diskontování budoucích splátek.</li><li>Nižší poplatky samy neurčují výhodnější investici. Různé fondy, akciové ETF a strategie DPS se liší složením a rizikem. Shodných 8 % je pouze matematický scénář, nikoli prognóza těchto fondů.</li></ul><p>${methodology}</p><p>${disclaimer}</p><h3>Ověřené zdroje · 30. 10. 2026</h3>${sources.map(([t,u])=>`<a class="source" href="${u}" target="_blank" rel="noopener noreferrer">${t} ↗</a>`).join('')}</section></div></div>`;
document.getElementById('method').before(section);
const nav=document.createElement('button');nav.className='nav';nav.dataset.tab='comparison';nav.textContent='DPS × DIP';document.querySelector('.menu-pages [data-tab="method"]').before(nav);
const tab=document.createElement('button');tab.setAttribute('role','tab');tab.setAttribute('aria-selected','false');tab.dataset.tab='comparison';tab.innerHTML='04 <span>DPS × DIP</span>';document.querySelector('.tabs').append(tab);
const $=id=>document.getElementById(id),status=t=>{$('cmp-status').textContent=t;},active=()=>!section.hidden;
function sync(){for(const e of section.querySelectorAll('[data-cmp]'))if(!['dipProfile','dpsProfile'].includes(e.dataset.cmp))e.value=state[e.dataset.cmp];}
const summaryRows=r=>{const a=r.dip.end,b=r.dps.end;return [['Vaše vklady',a.own,b.own],['Příspěvky firmy',a.employer,b.employer],['Státní příspěvky',a.state,b.state],['Vstupní náklady',a.entry,b.entry],['Průběžná správa / náklady',r.s.netReturns?'Obsaženo ve výnosu':a.management,r.s.netReturns?'Obsaženo ve výnosu':b.management],['Výkonnostní úplata (odhad)',0,r.s.netReturns?'Obsaženo ve výnosu':b.performance],['Zhodnocení po nákladech',a.gain,b.gain],['Hodnota před výstupní daní',a.value,b.value],['Modelová daň z výnosu',a.tax,b.tax],['Po modelové dani / kapitál pro penzi',a.net,b.net],['Daňová úspora mimo produkt',a.taxSaving,b.taxSaving],['Celkem včetně daňové úspory',a.total,b.total],['Celkem v dnešních cenách',a.real,b.real],['Volitelný bonus – hrubý odhad mimo součet',0,r.loyalty]];};
function render(){result=compare(state);state=result.s;const r=result;for(const kind of ['dip','dps'])$('cmp-'+kind).textContent=money(r[kind].end.total);$('cmp-verdict').textContent=(r.eligible&&r.excess===0?'V tomto scénáři ':'Pouze modelový rozdíl: ')+(Math.abs(r.difference)<1?'obě varianty vycházejí stejně.':(r.difference>0?'DIP':'DPS')+' o '+money(Math.abs(r.difference))+'.');$('cmp-why').textContent='Aktivní zadání: DIP vstup '+state.dipEntry+' %, roční náklady '+(state.netReturns?'již ve výnosu':state.dipFee+' %')+'; DPS vstup '+state.dpsEntry+' %, správa '+(state.netReturns?'již ve výnosu':state.dpsFee+' % + '+state.dpsPerformance+' % z kladného ročního zisku (odhad)')+'. Stát do DPS přidává '+money(r.support)+' měsíčně. Výnos DIP '+state.dipRate+' %, DPS '+state.dpsRate+' %. Výsledek není obecné pořadí produktů.';const warnings=[];if(!r.eligible)warnings.push('Horizont nesplňuje 10 let a věk 60. Částky nejsou řádně dostupné; předčasné ukončení by vyžadovalo další zdanění a vracení podpory.');if(r.excess)warnings.push('Nadlimitní příspěvek firmy '+money(r.excess)+' ročně: dodatečná daň a pojistné ze mzdy jsou mimo tento model.');if(state.loyalty)warnings.push(state.netReturns?'V čistém režimu nelze dopočítat bonus ze správy, která není samostatně vyčíslena.':'Volitelný model bonusu je mimo čistý součet; nejde o automatický nárok ani standardní podmínky DPS.');warnings.push('Pravidla ověřena k 30. 10. 2026; budoucí legislativa, příjmy a výnosy se mohou změnit.');warnings.push('Výkonnostní úplata DPS je zjednodušený odhad, nikoli přesný výpočet konkrétního fondu.');$('cmp-warning').textContent=warnings.join(' ');$('cmp-warning').classList.toggle('warning',!r.eligible||r.excess>0);
 $('cmp-summary').innerHTML=summaryRows(r).map(([t,a,b])=>`<tr><td>${t}</td><td>${typeof a==='number'?money(a):a}</td><td>${typeof b==='number'?money(b):b}</td></tr>`).join('');$('cmp-years').innerHTML=r.dip.rows.map((a,i)=>{const b=r.dps.rows[i];return `<tr><td>${a.year} / ${state.age+a.year}</td>${[a.value,b.value,a.net,b.net,a.taxSaving,b.taxSaving].map(x=>`<td>${money(x)}</td>`).join('')}</tr>`;}).join('');$('cmp-payout-note').textContent=(state.payout==='pension'?'DPS: kapitál pro penzi vyplácenou nejméně 10 let, nikoli jednorázová částka. ':'DPS: nová smlouva, jednorázově 15 % z kladného výnosu; příspěvek firmy se při řádné výplatě znovu nedaní. ')+(state.dipTax==='exempt'?'DIP: osvobození všech prodejů je vámi zvolený předpoklad; nenastává automaticky po 20 letech.':'DIP: hodnotový test 100 000 Kč a časový test každé investice samostatně; modelová sazba 15 / 23 % podle zadaného příjmu.');for(const k of ['dipFee','dpsFee','dpsPerformance'])section.querySelector(`[data-cmp="${k}"]`).disabled=!!state.netReturns;draw();}
function chartSvg(r,W=800,H=300){const L=65,R=15,T=20,B=35,max=Math.max(1,...r.points.flatMap(p=>[p.dip,p.dps,p.dipReal,p.dpsReal])),x=n=>L+n/r.s.years*(W-L-R),y=n=>H-B-n/max*(H-T-B);let svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}"><title>Vývoj DIP a DPS po modelové dani včetně kumulované daňové úspory bez reinvestování</title>`;for(let i=0;i<=4;i++){const v=max*i/4;svg+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#e8ddc8"/><text x="${L-8}" y="${y(v)+4}" text-anchor="end" font-size="11" fill="#75674f">${Math.round(v/1000)} tis.</text>`;}for(const [k,color,dash] of [['dip','#2563eb',''],['dps','#111111',''],['dipReal','#dc2626','4 4'],['dpsReal','#dc2626','10 5']])svg+=`<polyline fill="none" stroke="${color}" stroke-width="2.5" stroke-dasharray="${dash}" points="${r.points.map(p=>`${x(p.year)},${y(p[k])}`).join(' ')}"/>`;for(const n of [...new Set([0,Math.round(r.s.years/2),r.s.years])])svg+=`<text x="${x(n)}" y="${H-9}" text-anchor="${n===0?'start':n===r.s.years?'end':'middle'}" font-size="12" fill="#75674f">${n} let</text>`;return svg+'</svg>';}
function draw(){if(result)$('cmp-chart').innerHTML=chartSvg(result,Math.max(280,$('cmp-chart').clientWidth||800));}
for(const e of section.querySelectorAll('[data-cmp]'))e.addEventListener('change',()=>{const k=e.dataset.cmp;if(k==='dpsProfile'){if(e.value!=='custom'){state.dpsEntry=0;state.dpsFee=e.value==='conservative'?.4:1;state.dpsPerformance=e.value==='conservative'?10:15;sync();}}else if(k==='dipProfile'){if(e.value!=='custom'){state.dipEntry=e.value==='model'?3:0;state.dipFee=e.value==='model'?2.16:.4;sync();}}else{if(!e.checkValidity())return;state=cleanComparison({...state,[k]:e.value});if(['dpsEntry','dpsFee','dpsPerformance'].includes(k))section.querySelector('[data-cmp="dpsProfile"]').value='custom';if(['dipEntry','dipFee'].includes(k))section.querySelector('[data-cmp="dipProfile"]').value='custom';}render();});
for(const e of section.querySelectorAll('input[data-cmp]'))e.addEventListener('input',()=>{if(!e.checkValidity()||e.value==='')return;state=cleanComparison({...state,[e.dataset.cmp]:Number(e.value)});if(['dpsEntry','dpsFee','dpsPerformance'].includes(e.dataset.cmp))section.querySelector('[data-cmp="dpsProfile"]').value='custom';if(['dipEntry','dipFee'].includes(e.dataset.cmp))section.querySelector('[data-cmp="dipProfile"]').value='custom';render();});
function save(){try{localStorage.setItem(key,JSON.stringify(state));status('Srovnání uloženo v tomto prohlížeči.');}catch{status('Uložení není dostupné. Použijte JSON export.');}}
function reset(){state={...COMP_DEFAULTS};sync();section.querySelector('[data-cmp="dipProfile"]').value='model';render();section.querySelector('[data-cmp="dpsProfile"]').value='dynamic';status('Obnoven výchozí příklad; uložená kopie zůstala zachována.');}
$('cmp-save').onclick=save;$('cmp-reset').onclick=reset;
const xml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
const workbookSheet=rows=>`<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><cols><col min="1" max="1" width="45" customWidth="1"/><col min="2" max="8" width="24" customWidth="1"/></cols><sheetData>${rows.map((row,i)=>`<row r="${i+1}">${row.map((v,j)=>{const ref=String.fromCharCode(65+j)+(i+1);return typeof v==='number'?`<c r="${ref}"><v>${v}</v></c>`:`<c r="${ref}" t="inlineStr"><is><t xml:space="preserve">${xml(v)}</t></is></c>`;}).join('')}</row>`).join('')}</sheetData></worksheet>`;
function reportRows(r){return [['DPS × DIP · MŮJ-DIP · Jiří Janoušek'],['Pravidla 2026, nové smlouvy. '+(r.eligible?'Řádný horizont.':'NESPLNĚN ŘÁDNÝ HORIZONT.')],['Položka','DIP Kč','DPS Kč'],...summaryRows(r),['Upozornění',disclaimer],['Metodika',methodology],['Výplata DPS',r.s.payout==='pension'?'Kapitál pro nejméně 10letou penzi, nikoli hotovost nyní.':'Jednorázová výplata.'],['DIP daň',r.s.dipTax+'; hodnotový test 100 000 Kč a modelové sazby 15 / 23 %, bez dividend a jiných nezadaných příjmů.'],['Volitelný bonus','Pouze ilustrační model 25 % správy do 65 let, nikoli standardní vlastnost DPS. Odhad je před případnou daní a mimo čistý součet.'],['Nadlimitní příspěvek firmy ročně',r.excess,'Dodatečné odvody nejsou zahrnuty.'],...sources.map(([t,u])=>[t,u])];}
function yearRows(r){return [['Rok','Věk','DIP před daní','DPS před daní','DIP po dani','DPS po dani','Úspora DIP','Úspora DPS'],...r.dip.rows.map((a,i)=>{const b=r.dps.rows[i];return [a.year,r.s.age+a.year,a.value,b.value,a.net,b.net,a.taxSaving,b.taxSaving];})];}
export function comparisonXlsx(r){const names=['Srovnani','Vyvoj','Nastaveni'],rows=[reportRows(r),yearRows(r),[['Nastavení DPS × DIP'],['Název','Hodnota'],...Object.entries(r.s).map(([k,v])=>[titles[k]||k,v])]],files={'[Content_Types].xml':`<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>${names.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`,'_rels/.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>','xl/workbook.xml':`<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${names.map((n,i)=>`<sheet name="${n}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`,'xl/_rels/workbook.xml.rels':`<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${names.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}</Relationships>`};rows.forEach((v,i)=>files[`xl/worksheets/sheet${i+1}.xml`]=workbookSheet(v));return zip(files);}
async function imageExport(format,r){await document.fonts.ready;const W=1240,H=1754,pages=[];let c,g,y;const text=(t,x,yy,size=22,color='#242019')=>{g.font=`${size}px Arial`;g.fillStyle=color;g.fillText(String(t),x,yy);};const page=title=>{c=document.createElement('canvas');c.width=W;c.height=H;g=c.getContext('2d');g.fillStyle='#fffaf0';g.fillRect(0,0,W,H);text('MŮJ-DIP · Jiří Janoušek',70,65,22,'#9a7128');text(title,70,120,34);text('Orientační scénář bez záruky. Výnos není garantovaný.',70,H-55,19);pages.push(c);y=175;};const paragraph=t=>{const words=t.split(/\s+/).flatMap(w=>w.match(/.{1,65}/gu)||[]);let line='';for(const word of words){g.font='20px Arial';if(g.measureText(line+' '+word).width>1090){if(y>H-110)page('DPS × DIP · pokračování');text(line,70,y,20);y+=29;line=word;}else line+=(line?' ':'')+word;}if(line){text(line,70,y,20);y+=40;}};
page('DPS × DIP · přehled výsledků');paragraph(`${r.s.years} let · věk ${r.s.age} až ${r.s.age+r.s.years} · vlastní ${money(r.s.own)} / měsíc · firma ${money(r.s.employer)} / měsíc. ${r.eligible?'Řádný horizont.':'POZOR: nesplněny podmínky řádné výplaty.'}`);paragraph(`DIP: výnos ${r.s.dipRate} %, vstup ${r.s.dipEntry} %, roční náklady ${r.s.dipFee} %. DPS: výnos ${r.s.dpsRate} %, vstup ${r.s.dpsEntry} %, správa ${r.s.dpsFee} %, výkonnostní úplata ${r.s.dpsPerformance} %. ${r.s.netReturns?'Výnosy již po průběžných nákladech.':'Výnosy před náklady.'}`);
text('Položka',70,y,21);text('DIP',660,y,21,'#2563eb');text('DPS',920,y,21,'#111111');y+=40;for(const [t,a,b] of summaryRows(r)){text(t.startsWith('Volitelný bonus')?'Volitelný bonus (hrubý odhad mimo součet)':t,70,y,19);text(typeof a==='number'?money(a):a,660,y,19);text(typeof b==='number'?money(b):b,920,y,19);y+=39;}
const svg=chartSvg(r,1100,340),img=new Image(),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url;});g.drawImage(img,70,y,1100,340);y+=375;}finally{URL.revokeObjectURL(url);}paragraph('Graf: DIP modře, DPS černě, kupní síla po inflaci červeně (DIP krátké / DPS dlouhé čárky). Po modelové dani při řádném výběru v daném roce včetně kumulované daňové úspory mimo produkt, bez jejího reinvestování. Koncové hodnoty odpovídají součtům v přehledu. Daň není průběžně odečítána každý rok.');
page('DPS × DIP · nastavení a metodika');for(const [k,v] of Object.entries(r.s))paragraph((titles[k]||k)+': '+v);paragraph(methodology);paragraph(disclaimer);paragraph('DIP daň: režim test posuzuje hrubé prodeje do 100 000 Kč a stáří každého nákupu. Neosvobozený zisk podléhá modelu 15 / 23 % podle uvedeného příjmu. Dividendy a nezadané příjmy nejsou zahrnuty.');paragraph(r.s.payout==='pension'?'DPS: kapitál pro penzi alespoň 10 let, bez diskontování a následného zhodnocení. Nejde o jednorázovou hotovost.':'DPS: nová smlouva, jednorázová daň 15 % kladného výnosu; příspěvky zaměstnavatele při řádné výplatě bez další daně.');if(r.excess)paragraph('POZOR: roční nadlimitní příspěvek firmy '+money(r.excess)+'; dodatečná daň a odvody mimo výpočet.');for(const [t,u] of sources){paragraph(t);paragraph(u);}
page('DPS × DIP · roční vývoj');paragraph('Řádná výstupní daň je modelová; před splněním podmínek částky nejsou dostupné bez dopadů předčasného ukončení. Částky v Kč; úspory daně nejsou v hodnotě portfolia.');const heads=()=>{['Rok / věk','DIP před daní','DPS před daní','DIP po dani','DPS po dani'].forEach((t,i)=>text(t,[70,270,510,750,990][i],y,17));y+=40;};heads();for(const a of r.dip.rows){if(y>H-120){page('DPS × DIP · vývoj pokračování');heads();}const b=r.dps.rows[a.year-1];[`${a.year} / ${r.s.age+a.year}`,...[a.value,b.value,a.net,b.net].map(n=>new Intl.NumberFormat('cs-CZ',{maximumFractionDigits:0}).format(n))].forEach((t,i)=>text(t,[70,270,510,750,990][i],y,18));y+=37;}
if(format==='png'){const all=document.createElement('canvas');all.width=W;all.height=H*pages.length;if(all.height>30000)throw Error('Výstup je příliš dlouhý pro PNG. Použijte PDF.');const ctx=all.getContext('2d');pages.forEach((p,i)=>ctx.drawImage(p,0,i*H));const blob=await new Promise(resolve=>all.toBlob(resolve,'image/png'));if(!blob)throw Error('PNG se nepodařilo vytvořit.');saveFile('MUJ-DIP-DPS-srovnani.png',blob,'image/png');}else{const images=pages.map(p=>Uint8Array.from(atob(p.toDataURL('image/jpeg',.92).split(',')[1]),ch=>ch.charCodeAt(0)));saveFile('MUJ-DIP-DPS-srovnani.pdf',jpegPdf(images,W,H),'application/pdf');}}
async function exportComparison(format){try{status('Připravuji výstup…');if(format==='xlsx')saveFile('MUJ-DIP-DPS-srovnani.xlsx',comparisonXlsx(result),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');else if(format==='csv')saveFile('MUJ-DIP-DPS-vyvoj.csv','\uFEFF'+yearRows(result).map(row=>row.map(v=>typeof v==='number'?v.toFixed(2):v).join(';')).join('\r\n'),'text/csv;charset=utf-8');else if(format==='json')saveFile('MUJ-DIP-DPS-plan.json',JSON.stringify({app:'MUJ-DIP-DPS',version:1,settings:state},null,2),'application/json');else await imageExport(format,result);status('Srovnání je připraveno ke stažení.');}catch(e){status('Export se nezdařil: '+e.message);}}
for(const e of section.querySelectorAll('[data-cmp-export]'))e.onclick=()=>exportComparison(e.dataset.cmpExport);
async function importComparison(file){if(!file)return;try{if(file.size>100000)throw Error('Soubor je příliš velký.');const data=JSON.parse(await file.text());if(data.app!=='MUJ-DIP-DPS'||data.version!==1||!data.settings||Object.keys(COMP_DEFAULTS).some(k=>k!=='otherSales'&&!(k in data.settings)))throw Error('Použijte JSON export srovnání DPS × DIP.');for(const k in COMP_DEFAULTS){if(['dipTax','payout'].includes(k)||k==='otherSales'&&!(k in data.settings))continue;if(typeof data.settings[k]!=='number'||!Number.isFinite(data.settings[k]))throw Error('Neplatné číselné nastavení.');}state=cleanComparison(data.settings);sync();section.querySelector('[data-cmp="dipProfile"]').value='custom';section.querySelector('[data-cmp="dpsProfile"]').value='custom';render();status('Srovnání načteno.');}catch(e){status('Import: '+e.message);}}
$('cmp-import').onchange=async e=>{await importComparison(e.target.files[0]);e.target.value='';};
for(const [id,handler] of [['save',save],['reset',reset],['export',()=>exportComparison($('exportFormat').value)],['print',()=>exportComparison('pdf')]])$(id).addEventListener('click',e=>{if(active()){e.preventDefault();e.stopImmediatePropagation();handler();}},true);
$('import').addEventListener('change',async e=>{if(!active())return;e.stopImmediatePropagation();await importComparison(e.target.files[0]);e.target.value='';},true);
if(state.dpsFee!==1||state.dpsPerformance!==15||state.dpsEntry!==0)section.querySelector('[data-cmp="dpsProfile"]').value='custom';new ResizeObserver(draw).observe($('cmp-chart'));sync();if(state.dipFee!==2.16||state.dipEntry!==3)section.querySelector('[data-cmp="dipProfile"]').value='custom';render();
